import type { MetadataRoute } from "next";

/** Metadata routes are Route Handlers; `output: "export"` requires this. */
export const dynamic = "force-static";

/**
 * Installable-app metadata. Icons are the "seam" mark on its accent-900 tile,
 * generated by scripts/generate-brand-assets.mjs.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Transmute — Free Online File Conversion Tools",
    short_name: "Transmute",
    description:
      "Free, private, browser-based file conversion tools. Convert images, PDFs, audio, video, and more — no uploads, no sign-ups.",
    start_url: "/",
    display: "standalone",
    background_color: "#0f111c",
    theme_color: "#161826",
    categories: ["utilities", "productivity"],
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
      {
        src: "/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
